#include "stm32f103.h"

// PB0 bit-bang PWM: 1 ms then 2 ms pulses.
// SG90 model displays commanded angle, without load dynamics.
int main(void) {
  board_gpio_output(GPIOB, 0);
  for (;;) {
    for (int n = 0; n < 25; n++) {
      board_gpio_write(GPIOB, 0, 1);
      board_delay_ms(1);
      board_gpio_write(GPIOB, 0, 0);
      board_delay_ms(19);
    }
    for (int n = 0; n < 25; n++) {
      board_gpio_write(GPIOB, 0, 1);
      board_delay_ms(2);
      board_gpio_write(GPIOB, 0, 0);
      board_delay_ms(18);
    }
  }
}
